const j = $input.first().json;
let query, language, limit;

// Helper to parse a field that might be a JSON string like '{"query":"...","limit":5}'
function extractFromJsonOrString(val) {
  if (typeof val !== 'string' || !val.trim()) return { query: null, limit: null, language: null };
  const t = val.trim();
  if (t.startsWith('{')) {
    try {
      const p = JSON.parse(t);
      return {
        query: typeof p.query === 'string' && p.query.trim() ? p.query.trim() : null,
        limit: (p.limit !== null && p.limit !== undefined && Number.isFinite(Number(p.limit)) && Number(p.limit) > 0) ? Number(p.limit) : null,
        language: typeof p.language === 'string' ? p.language.trim().toLowerCase() : null
      };
    } catch {}
  }
  return { query: t, limit: null, language: null };
}

if (j.input && typeof j.input === 'string' && j.input.trim()) {
  const parsed = extractFromJsonOrString(j.input);
  query = parsed.query || '';
  language = parsed.language || 'spa';
  limit = parsed.limit ? Math.max(1, Math.min(8, parsed.limit)) : 5;
} else if (j.input && typeof j.input === 'object') {
  query = (j.input.query || '').trim();
  language = typeof j.input.language === 'string' ? j.input.language.trim().toLowerCase() : 'spa';
  const rl = j.input.limit;
  limit = (rl !== null && rl !== undefined && Number.isFinite(Number(rl)) && Number(rl) > 0) ? Math.max(1, Math.min(8, Number(rl))) : 5;
} else if (typeof j.query === 'string' && j.query.trim()) {
  // query field might be a plain search string OR a JSON string
  const parsed = extractFromJsonOrString(j.query);
  query = parsed.query || '';
  language = parsed.language || (typeof j.language === 'string' ? j.language.trim().toLowerCase() : 'spa');
  limit = parsed.limit ? Math.max(1, Math.min(8, parsed.limit)) : 5;
} else {
  query = '';
  language = 'spa';
  limit = 5;
}

if (!query) {
  return [{ json: { books: [], count: 0, error: 'ERROR: query required. Call with: {"query":"brandon sanderson","limit":5}' } }];
}
return [{ json: { query, language, limit } }];

// Extrae candidatos de Open Library y construye URLs de portada para validar
const params = $('Validar Input').first().json;
const olData = $input.first().json;

const docs = Array.isArray(olData.docs) ? olData.docs : [];
const candidates = [];

for (const doc of docs.slice(0, (params.limit || 5) * 2)) {
  const title = doc.title || '';
  const author = Array.isArray(doc.author_name) ? doc.author_name[0] : null;
  const isbn = Array.isArray(doc.isbn) ? doc.isbn.find(i => i.length === 13 || i.length === 10) : null;
  const coverId = doc.cover_i ? String(doc.cover_i) : null;
  const coverEditionKey = doc.cover_edition_key || null;
  const year = doc.first_publish_year || null;

  if (!title || !author) continue;

  // Candidatos de portada, de mayor a menor calidad esperada
  const coverCandidates = [];
  if (coverId) coverCandidates.push(`https://covers.openlibrary.org/b/id/${coverId}-L.jpg`);
  if (coverEditionKey) coverCandidates.push(`https://covers.openlibrary.org/b/olid/${coverEditionKey}-L.jpg`);
  if (isbn) coverCandidates.push(`https://covers.openlibrary.org/b/isbn/${isbn}-L.jpg`);

  candidates.push({ title, author, isbn, year, coverCandidates, olKey: doc.key });
}

return [{ json: { candidates, query: params.query, language: params.language, limit: params.limit } }];

// Trust OL covers directly when cover_i exists — skip slow/broken HEAD validation
// Open Library cover IDs are reliable indicators that a cover exists
const data = $input.first().json;
const { candidates, query, language, limit } = data;

const results = [];
const needsGoogleBooks = [];

for (const cand of candidates) {
  if (results.length >= limit) break;

  // Use first cover candidate (cover_i URL) directly
  const coverUrl = cand.coverCandidates && cand.coverCandidates.length > 0
    ? cand.coverCandidates[0]
    : null;

  if (coverUrl) {
    results.push({
      title: cand.title,
      author: cand.author,
      isbn: cand.isbn,
      year: cand.year,
      coverUrl,
      coverAvailable: true,
      source: 'open_library',
      language
    });
  } else {
    needsGoogleBooks.push({ title: cand.title, author: cand.author, isbn: cand.isbn });
  }
}

const remaining = Math.max(0, limit - results.length);
return [{ json: { results, needsGoogleBooks: needsGoogleBooks.slice(0, remaining), remaining, query, language, limit } }];

// Process Google Books results — no HEAD validation needed (just skip missing thumbnails)
const olData = $('Validar Portadas OL').first().json;
const gbData = $input.first().json;

const items = Array.isArray(gbData.items) ? gbData.items : [];
const results = [...(olData.results || [])];
const seen = new Set(results.map(r => r.title.toLowerCase()));

for (const item of items) {
  if (results.length >= (olData.limit || 5)) break;
  const vi = item.volumeInfo || {};
  const title = vi.title || '';
  const author = Array.isArray(vi.authors) ? vi.authors[0] : null;
  if (!title || !author || seen.has(title.toLowerCase())) continue;
  seen.add(title.toLowerCase());

  const rawThumb = vi.imageLinks?.thumbnail || vi.imageLinks?.smallThumbnail || null;
  if (!rawThumb) continue;

  // Upgrade thumbnail to high resolution
  let coverUrl = rawThumb
    .replace('http://', 'https://')
    .replace(/&edge=curl/g, '')
    .replace(/zoom=\d+/, 'zoom=0');
  if (!coverUrl.includes('zoom=')) coverUrl += '&zoom=0';
  if (!coverUrl.includes('fife=')) coverUrl += '&fife=w800-h1200';

  const isbn = (vi.industryIdentifiers || []).find(i => i.type === 'ISBN_13')?.identifier
    || (vi.industryIdentifiers || []).find(i => i.type === 'ISBN_10')?.identifier
    || null;

  results.push({
    title, author, isbn,
    year: vi.publishedDate ? parseInt(vi.publishedDate, 10) : null,
    coverUrl,
    coverAvailable: true,
    source: 'google_books',
    language: olData.language || 'es',
    description: vi.description ? vi.description.slice(0, 1000) : null
  });
}

return [{ json: { books: results } }];

// Rama directa: OL tiene suficientes resultados, pasar directamente
const olData = $input.first().json;
return [{ json: { books: olData.results || [] } }];

// Deduplica y devuelve la lista final con descripción enriquecida
const allItems = $input.all();
const seen = new Set();
const books = [];

for (const item of allItems) {
  const src = item.json?.books || item.json?.book ? [item.json] : [];
  const arr = item.json?.books || [];
  for (const b of arr) {
    const key = b.title?.toLowerCase() || '';
    if (!key || seen.has(key)) continue;
    seen.add(key);
    books.push({
      title: b.title || '',
      author: b.author || '',
      isbn: b.isbn || null,
      year: b.year || null,
      description: b.description || null,
      coverUrl: b.coverUrl || null,
      coverAvailable: b.coverAvailable === true,
      source: b.source || 'unknown',
      language: b.language || 'es'
    });
  }
}

return [{ json: { books, count: books.length } }];
